import SafariServices
import Foundation

// Compile in the Safari extension target generated by safari-web-extension-converter.
// The containing app is the native host; only its bundled extension can call this handler.
class SafariWebExtensionHandler: NSObject, NSExtensionRequestHandling {
    func beginRequest(with context: NSExtensionContext) {
        guard let item = context.inputItems.first as? NSExtensionItem,
              let message = item.userInfo?[SFExtensionMessageKey] as? [String: Any],
              message["origin"] as? String == "https://www.bookleap.cn",
              let input = message["request"] as? [String: Any],
              let route = input["route"] as? String,
              ["/pair", "/status", "/snapshot"].contains(route),
              let url = URL(string: "http://127.0.0.1:48720" + route) else {
            reply(context, status: 403, body: ["error": "invalid_native_request"]); return
        }
        var request = URLRequest(url: url, timeoutInterval: 15)
        request.httpMethod = route == "/status" ? "GET" : "POST"
        request.setValue("https://www.bookleap.cn", forHTTPHeaderField: "Origin")
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.setValue("1", forHTTPHeaderField: "X-BookLeap-Protocol")
        if let token = input["token"] as? String { request.setValue("Bearer " + token, forHTTPHeaderField: "Authorization") }
        if route != "/status" {
            guard let body = input["body"], JSONSerialization.isValidJSONObject(body),
                  let data = try? JSONSerialization.data(withJSONObject: body), data.count <= 32 * 1024 * 1024 else {
                reply(context, status: 413, body: ["error": "snapshot_too_large"]); return
            }
            request.httpBody = data
        }
        URLSession.shared.dataTask(with: request) { data, response, error in
            guard error == nil, let data, let response = response as? HTTPURLResponse,
                  let body = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
                self.reply(context, status: 503, body: ["error": "native_host_unavailable"]); return
            }
            self.reply(context, status: response.statusCode, body: body)
        }.resume()
    }
    private func reply(_ context: NSExtensionContext, status: Int, body: [String: Any]) {
        let item = NSExtensionItem()
        item.userInfo = [SFExtensionMessageKey: ["status": status, "body": body]]
        context.completeRequest(returningItems: [item])
    }
}
